package org.marketreview.nativeapp;
import android.content.Context;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.LocalDate;
import java.util.*;
import java.util.function.Supplier;
import java.util.function.Consumer;
/** Native internal account analysis; no broker, network, or history rewriting. */
final class AccountAnalysisScreen extends LinearLayout {
 Consumer<String> accountChanged;Runnable returnToAccount;
 private final BusinessStore store;private final boolean paper;private final Supplier<JSONArray> roster;private final Spinner accounts;private final List<String> ids=new ArrayList<>();private final TextView summary,state;private final LinearLayout content;private JSONObject active=new JSONObject(),output=new JSONObject();private boolean filling,dark;private int mode;private String lastAccount="";
 AccountAnalysisScreen(Context c,BusinessStore s,boolean paper,Supplier<JSONArray> roster){super(c);store=s;this.paper=paper;this.roster=roster;setOrientation(VERTICAL);setTag("accountAnalysisScreen");LinearLayout toolbar=new LinearLayout(c);addView(toolbar);accounts=new Spinner(c);accounts.setTag("analysisAccount");toolbar.addView(accounts,new LayoutParams(0,-2,2));button(toolbar,"重读","analysisReload",()->reload());summary=text("");summary.setTag("analysisSummary");summary.setMaxLines(4);addView(summary);LinearLayout modes=new LinearLayout(c);addView(modes);button(modes,"结构 / 盈亏","analysisStructureMode",()->{mode=0;render();});button(modes,"历史权益 / 现金","analysisHistoryMode",()->{mode=1;render();});button(modes,"记录现金流","analysisFlowMode",()->{mode=2;render();});button(modes,"账户","analysisAccountMode",()->{if(returnToAccount!=null)returnToAccount.run();});ScrollView scroll=new ScrollView(c);content=new LinearLayout(c);content.setOrientation(VERTICAL);scroll.addView(content);addView(scroll,new LayoutParams(-1,0,1));state=text("");state.setTag("analysisState");state.setMaxLines(3);addView(state);
  accounts.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int at,long id){if(!filling&&at>=0&&at<ids.size()&&!ids.get(at).equals(lastAccount)){lastAccount=ids.get(at);reload();if(accountChanged!=null)accountChanged.accept(lastAccount);}}});reload();
 }
 private TextView text(String s){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(13);t.setPadding(6,4,6,4);t.setTextColor(dark?0xffdae5f5:0xff1f3048);return t;}
 private Button button(LinearLayout parent,String title,String tag,Runnable run){Button b=new Button(getContext());b.setText(title);b.setTag(tag);b.setTextSize(12);b.setAllCaps(false);parent.addView(b,new LayoutParams(0,-2,1));b.setOnClickListener(v->run.run());return b;}
 void setDarkTheme(boolean value){dark=value;setBackgroundColor(dark?0xff101a27:0xffffffff);colors(this);render();}
 private void colors(View v){if(v instanceof LinearLayout||v instanceof ScrollView)v.setBackgroundColor(dark?0xff101a27:0xffffffff);if(v instanceof TextView)((TextView)v).setTextColor(dark?0xffdae5f5:0xff1f3048);if(v instanceof EditText)((EditText)v).setHintTextColor(dark?0xff9eb3cb:0xff65778b);if(v instanceof Button)v.setBackgroundTintList(android.content.res.ColorStateList.valueOf(dark?0xff26394f:0xffe9eef5));if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++)colors(group.getChildAt(i));}}
 void setAccount(String id){reload();int at=ids.indexOf(id);if(at>=0){filling=true;accounts.setSelection(at);filling=false;reload();}}
 void reload(){try{String keep=ids.isEmpty()?"":ids.get(Math.max(0,accounts.getSelectedItemPosition()));filling=true;ids.clear();List<String> names=new ArrayList<>();JSONArray list=store.read("accounts");for(int i=0;i<list.length();i++){JSONObject a=list.getJSONObject(i);if(a.optString("type").equals("paper")!=paper)continue;ids.add(a.optString("id"));names.add(a.optString("name"));}ArrayAdapter<String> adapter=new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_item,names){public View getView(int at,View old,ViewGroup parent){TextView t=(TextView)super.getView(at,old,parent);t.setTextColor(dark?0xffdae5f5:0xff1f3048);return t;}public View getDropDownView(int at,View old,ViewGroup parent){TextView t=(TextView)super.getDropDownView(at,old,parent);t.setTextColor(dark?0xffdae5f5:0xff1f3048);t.setBackgroundColor(dark?0xff182534:0xffffffff);return t;}};adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);accounts.setAdapter(adapter);accounts.setSelection(Math.max(0,ids.indexOf(keep)));if(ids.isEmpty()){active=new JSONObject();output=new JSONObject();lastAccount="";summary.setText("");content.removeAllViews();if(summary.getParent() instanceof ViewGroup)((ViewGroup)summary.getParent()).removeView(summary);if(state.getParent() instanceof ViewGroup)((ViewGroup)state.getParent()).removeView(state);content.addView(summary);content.addView(state);filling=false;state.setText("此范围没有账户；前账户结果已清除");return;}lastAccount=ids.get(accounts.getSelectedItemPosition());for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optString("id").equals(lastAccount))active=list.getJSONObject(i);JSONObject quotes=new JSONObject();JSONArray rows=roster==null?new JSONArray():roster.get();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);quotes.put(r.optString("id"),r.optJSONObject("quote"));}output=AccountAnalysis.evaluate(active,store.read("trades"),quotes,store.read("reports"));summary.setText("成本 "+AccountAnalysis.display(output.opt("cost"))+" · 市值 "+AccountAnalysis.display(output.opt("marketValue"))+" · 输入现金 "+AccountAnalysis.display(output.opt("cashBalance"))+" · 合计 "+AccountAnalysis.display(output.opt("totalAssets"))+" 元\n已实现 "+AccountAnalysis.display(output.opt("realized"))+" · 浮盈 "+AccountAnalysis.display(output.opt("unrealized"))+" · 累计盈亏 "+AccountAnalysis.display(output.opt("totalPnl"))+" 元\n现金时点 "+active.optString("cashAsOf","未提供（可能是旧账户记录）"));filling=false;state.setText(output.optString("boundary"));render();}catch(Exception e){filling=false;state.setText(e.getMessage());}}
 private void render(){if(content==null)return;try{content.removeAllViews();if(summary.getParent() instanceof ViewGroup)((ViewGroup)summary.getParent()).removeView(summary);if(state.getParent() instanceof ViewGroup)((ViewGroup)state.getParent()).removeView(state);if(mode==0){JSONArray rows=output.optJSONArray("positions");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);TextView t=text(r.optString("name")+" · "+r.optString("instrumentId")+"\n"+r.optLong("quantity")+"股 · 成本 "+AccountAnalysis.display(r.opt("cost"))+"元 / "+AccountAnalysis.display(r.opt("costWeightPercent"))+"% · 市值 "+AccountAnalysis.display(r.opt("marketValue"))+"元 / 资产权重 "+AccountAnalysis.display(r.opt("marketWeightPercent"))+"%\n已实现 "+AccountAnalysis.display(r.opt("realized"))+" · 浮盈 "+AccountAnalysis.display(r.opt("unrealized"))+" · 累计盈亏 "+AccountAnalysis.display(r.opt("totalPnl"))+" 元\n报价 "+r.optString("quoteDate","未知")+" "+r.optString("quoteTime","未知")+" · "+r.optString("quoteSource")+(r.optBoolean("quoteCached")?"（旧缓存）":""));t.setTag("analysisPosition_"+i);content.addView(t);}}else if(mode==1){JSONArray rows=output.optJSONArray("history");if(rows!=null){HistoryPlot plot=new HistoryPlot(getContext(),rows);plot.setTag("analysisHistoryPlot");content.addView(plot,new LayoutParams(-1,Math.round(220*getResources().getDisplayMetrics().density)));for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);TextView t=text(r.optString("date")+" · 总资产 "+AccountAnalysis.display(r.opt("totalAssets"))+" · 现金 "+AccountAnalysis.display(r.opt("cashBalance"))+" · 市值 "+AccountAnalysis.display(r.opt("marketValue"))+" 元\n资产变化 "+AccountAnalysis.display(r.opt("assetChange"))+"元（非净收益） · 原累计盈亏 "+AccountAnalysis.display(r.opt("totalPnl"))+"元 · 算术一致 "+r.optBoolean("arithmeticConsistent")+"\n点击展开原记录");t.setTag("analysisSnapshot_"+i);TextView original=text(r.getJSONObject("original").toString(2));original.setTag("analysisOriginal_"+i);original.setTextIsSelectable(true);original.setVisibility(GONE);t.setOnClickListener(v->original.setVisibility(original.getVisibility()==GONE?VISIBLE:GONE));content.addView(t);content.addView(original);}}}else{JSONArray rows=output.optJSONArray("cashPath");content.addView(text("记录净现金流 "+AccountAnalysis.display(output.opt("recordedCashFlow"))+"元；不是当前现金余额，缺外部出入金记录。"));if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);content.addView(text(r.optString("date")+" · "+r.optString("instrumentId")+" · "+r.optString("side")+"\n记录现金流 "+AccountAnalysis.display(r.opt("cashDelta"))+" · 累计记录流 "+AccountAnalysis.display(r.opt("cumulativeRecordedFlow"))+" 元"));}}content.addView(summary);content.addView(state);colors(content);}catch(Exception e){state.setText(e.getMessage());}}
 JSONObject saveState()throws JSONException{return new JSONObject().put("schema","account-analysis-drafts/v1").put("account",active.optString("id")).put("mode",mode);}
 void restoreState(JSONObject s){try{BusinessStore.require(s.optString("schema").equals("account-analysis-drafts/v1"),"账户草稿格式无效");mode=Math.max(0,Math.min(2,s.optInt("mode")));setAccount(s.optString("account"));render();}catch(Exception e){state.setText(e.getMessage());}}
 private final class HistoryPlot extends View {
  final JSONArray rows;final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);HistoryPlot(Context c,JSONArray rows){super(c);this.rows=rows;}
  protected void onDraw(Canvas canvas){super.onDraw(canvas);float density=getResources().getDisplayMetrics().density;pen.setTextSize(12*density);pen.setColor(dark?0xffdae5f5:0xff1f3048);canvas.drawText("原快照总资产 / 现金 · 缺数断开，非收益率",6*density,18*density,pen);double min=Double.POSITIVE_INFINITY,max=Double.NEGATIVE_INFINITY;for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(!r.optBoolean("dateValid"))continue;for(String k:new String[]{"totalAssets","cashBalance"})if(r.opt(k) instanceof Number){min=Math.min(min,r.optDouble(k));max=Math.max(max,r.optDouble(k));}}if(!Double.isFinite(min)){canvas.drawText("没有可画的原始历史数据，未补历史",6*density,48*density,pen);return;}if(max==min)max=min+1;canvas.drawText("蓝：总资产 / 橙：现金 · 按原记录顺序",6*density,36*density,pen);canvas.drawText(String.format(Locale.ROOT,"%.2f元",max),6*density,52*density,pen);canvas.drawText(String.format(Locale.ROOT,"%.2f元",min),6*density,getHeight()-40*density,pen);if(rows.length()>0)canvas.drawText(rows.optJSONObject(0).optString("date")+" → "+rows.optJSONObject(rows.length()-1).optString("date"),60*density,getHeight()-8*density,pen);float left=60*density,right=getWidth()-8*density,top=48*density,bottom=getHeight()-44*density;int line=0;for(String key:new String[]{"totalAssets","cashBalance"}){pen.setColor(line++==0?0xff477ac1:0xffcb9045);pen.setStrokeWidth(2*density);boolean last=false;float px=0,py=0;for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(!r.optBoolean("dateValid")||!(r.opt(key) instanceof Number)){last=false;continue;}float x=left+(right-left)*i/Math.max(1,rows.length()-1),y=(float)(bottom-(r.optDouble(key)-min)/(max-min)*(bottom-top));if(last)canvas.drawLine(px,py,x,y,pen);canvas.drawCircle(x,y,2*density,pen);last=true;px=x;py=y;}}}
 }
}
